        raise ParseError(bad.line, "stock of %s would go below zero" % bad.sku)
    return moves


# --------------------------------------------------------------------------- orders


def parse_orders(text: str, catalog) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, line in iter_lines(text):
        parts = _SEP_RE.split(line)
        if len(parts) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id = norm_order_id(parts[0])
        if order_id is None:
            raise ParseError(number, "bad order number %r (expected like SO-1001)" % parts[0])
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(parts[1])
        if date is None:
            raise ParseError(number, "bad date %r (expected a real YYYY-MM-DD)" % parts[1])
        lines = []  # type: List[Tuple[str, int]]
        used = set()
        for token in parts[3].split(","):
            pair = token.split("*")
            if len(pair) != 2:
                raise ParseError(number, "bad order line %r (expected SKU*QUANTITY)" % token)
            sku = norm_sku(pair[0])
            if sku is None or sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % pair[0])
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            if not is_positive_whole(pair[1]):
                raise ParseError(
                    number, "bad quantity %r (whole number of one or more)" % pair[1]
                )
            used.add(sku)
            lines.append((sku, to_int(pair[1])))
        seen.add(order_id)
        orders.append(Order(order_id, date, parts[2], lines, number))
    return orders
"""Stock levels, status, history and movement appending."""

import datetime
from typing import Dict, List, Tuple

from .parsing import Movement, sorted_movements


def stock_levels(catalog, movements) -> Dict[str, int]:
    """Quantity on the shelf for every catalogue SKU (0 when it never moved)."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        if move.sku in levels:
            levels[move.sku] += move.quantity
    return levels


def stock_status(onhand: int, reorder: int) -> str:
    if onhand == 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand: int, reorder: int) -> int:
    return max(1, 2 * reorder - onhand)


def history(sku: str, movements) -> List[Tuple[Movement, int]]:
    """(movement, balance after it) for one SKU, in counting order."""
    balance = 0
    rows = []
    for move in sorted_movements(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def available_on(sku: str, movements, date: datetime.date) -> int:
    """How many units of ``sku`` can leave on ``date`` without any later movement going negative."""
    running = 0
    best = None
    for move in sorted_movements(movements):
        if move.sku != sku:
            continue
        running += move.quantity
        if move.date > date:
            best = running if best is None else min(best, running)
    on_date = 0
    for move in sorted_movements(movements):
        if move.sku == sku and move.date <= date:
            on_date += move.quantity
    if best is not None:
        on_date = min(on_date, best)
    return max(0, on_date)


def format_movement(move: Movement) -> str:
    """The movements.txt line for a movement (no balance)."""
    line = "%s %s %+d" % (move.date.isoformat(), move.sku, move.quantity)
    return line + " " + move.note if move.note else line
"""Order status, shipped quantities, invoices and the report."""

from typing import Dict, List

from .parsing import Order
from .pricing import money, price_order


def shipped_quantities(order, movements) -> Dict[str, int]:
    """Units of each order line already shipped (movements noted ``order SO-N``), capped."""
    note = "order " + order.id
    sent = {}  # type: Dict[str, int]
    for move in movements:
        if move.quantity < 0 and move.note == note:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return {sku: min(sent.get(sku, 0), qty) for sku, qty in order.lines}


def order_status(order, shipped) -> str:
    owed = any(shipped.get(sku, 0) < qty for sku, qty in order.lines)
    if not owed:
        return "complete"
    if not any(shipped.get(sku, 0) > 0 for sku, _ in order.lines):
        return "open"
    return "partial"


def shipped_order(order, shipped) -> Order:
    """The order restricted to what has shipped (lines with nothing shipped left out)."""
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped.get(sku, 0) > 0]
    return Order(order.id, order.date, order.customer, lines, order.line)


def report_rows(orders, catalog, movements) -> List[dict]:
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, o.id)):
        shipped = shipped_quantities(order, movements)
        sent = shipped_order(order, shipped)
        invoiced = price_order(sent, catalog).total if sent.lines else money(0)
        quoted = price_order(order, catalog).total
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": order_status(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(shipped.values()),
                "quoted": quoted,
                "invoiced": invoiced,
            }
        )
    return rows
"""Order pricing: volume discount, order discount share-out, per-line tax. Exact to the penny."""

from dataclasses import dataclass
from decimal import Decimal
from typing import List

from .parsing import CTX

_TAX_PERCENT = {"standard": 20, "reduced": 5, "zero": 0}


def cents(amount: Decimal) -> int:
    """A two-decimal Decimal as a whole number of pennies."""
    return int(CTX.scaleb(amount, 2))


def money(pennies: int) -> Decimal:
    """Whole pennies as a Decimal with two decimal places."""
    return CTX.scaleb(Decimal(pennies), -2)


def _percent(pennies: int, percent: int) -> int:
    """percent % of a non-negative penny amount, rounded half up."""
    return (pennies * percent + 50) // 100


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def price_order(order, catalog) -> Quote:
    products = []
    for sku, _qty in order.lines:
        product = catalog.get(sku)
        if product is None:
            product = catalog[sku.upper()]
        products.append(product)

    units, grosses, discounts, nets = [], [], [], []
    for (_sku, qty), product in zip(order.lines, products):
        unit = cents(product.price)
        gross = qty * unit
        percent = 10 if qty >= 50 else 5 if qty >= 10 else 0
        discount = _percent(gross, percent)
        units.append(unit)
        grosses.append(gross)
        discounts.append(discount)
        nets.append(gross - discount)

    subtotal = sum(nets)
    order_discount = _percent(subtotal, 3) if subtotal >= 50000 else 0

    # Share the order discount out in whole pennies: round each share down, then hand the
    # leftover pennies one each to the lines that lost the most (earlier line on a tie).
    shares = [order_discount * net // subtotal if subtotal else 0 for net in nets]
    lost = [order_discount * net % subtotal if subtotal else 0 for net in nets]
    leftover = order_discount - sum(shares)
    ranking = sorted(range(len(nets)), key=lambda i: (-lost[i], i))
    for i in ranking[:leftover]:
        shares[i] += 1

    tax = 0
    for net, share, product in zip(nets, shares, products):
        tax += _percent(net - share, _TAX_PERCENT[product.tax])

    lines = [
        QuoteLine(
            sku,
            qty,
            money(units[i]),
            money(grosses[i]),
            money(-discounts[i]),
            money(nets[i]),
        )
        for i, (sku, qty) in enumerate(order.lines)
    ]
    return Quote(
        lines,
        money(subtotal),
        money(-order_discount),
        money(tax),
        money(subtotal - order_discount + tax),
    )

