"""Parsing of catalog.txt, movements.txt and orders.txt, plus the shared text rules."""

import datetime
import re
from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Context, Decimal
from typing import Dict, Iterator, List, Optional, Tuple

# Whitespace for separating and trimming is ASCII space and tab only.
WS = " \t"

# Exact-precision context for Decimal work, so huge numbers are never rounded silently.
CTX = Context(prec=1000000, rounding=ROUND_HALF_UP, Emax=999999999, Emin=-999999999)

TAXES = ("standard", "reduced", "zero")

_SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_UINT_RE = re.compile(r"[0-9]+")
_MOVE_QTY_RE = re.compile(r"[+-]?[0-9]+")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
_SEP_RE = re.compile(r"[ \t]+")
_PENNY = Decimal("0.01")


class ParseError(ValueError):
    """A mistake in a data file. ``.line`` is the 1-based line number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"


@dataclass(frozen=True)
class Movement:
    date: datetime.date
    sku: str
    quantity: int
    note: str = ""
    line: int = 0


@dataclass(frozen=True)
class Order:
    id: str
    date: datetime.date
    customer: str
    lines: List[Tuple[str, int]] = field(default_factory=list)
    line: int = 0


def to_int(text: str) -> int:
    """int() of an ASCII digit string with optional sign, with no digit-count limit."""
    return int(Decimal(text))


def norm_sku(text: str) -> Optional[str]:
    """Upper-case form of a well-formed SKU, or None."""
    if text.isascii() and _SKU_RE.fullmatch(text):
        return text.upper()
    return None


def norm_order_id(text: str) -> Optional[str]:
    if _ORDER_ID_RE.fullmatch(text):
        return text.upper()
    return None


def parse_date(text: str) -> Optional[datetime.date]:
    """A YYYY-MM-DD string that is a real calendar date, or None."""
    if not _DATE_RE.fullmatch(text):
        return None
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return None


def is_positive_whole(text: str) -> bool:
    return bool(_UINT_RE.fullmatch(text)) and to_int(text) >= 1


def iter_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield (line number, trimmed content) for every line that is not blank or a comment."""
    if text.startswith("﻿"):
        text = text[1:]
    for number, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        content = raw.strip(WS)
        if not content or content.startswith("#"):
            continue
        yield number, content


# --------------------------------------------------------------------------- catalogue


def parse_catalog(text: str) -> Dict[str, Product]:
    catalog = {}  # type: Dict[str, Product]
    for number, line in iter_lines(text):
        fields = [f.strip(WS) for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number, "expected 4 or 5 fields separated by '|', found %d" % len(fields)
            )
        sku_text, name, price_text, reorder_text = fields[:4]
        sku = norm_sku(sku_text)
        if sku is None:
            raise ParseError(number, "bad SKU %r (expected like AB-100)" % sku_text)
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "name is empty")
        if not _PRICE_RE.fullmatch(price_text):
            raise ParseError(number, "bad price %r (at most two decimals)" % price_text)
        price = CTX.quantize(Decimal(price_text), _PENNY)
        if price < _PENNY:
            raise ParseError(number, "price must be at least 0.01")
        if not _UINT_RE.fullmatch(reorder_text):
            raise ParseError(number, "bad reorder level %r (whole number, 0 or more)" % reorder_text)
        tax = "standard"
        if len(fields) == 5:
            tax_text = fields[4]
            if not (tax_text.isascii() and tax_text.lower() in TAXES):
                raise ParseError(
                    number, "bad tax %r (standard, reduced or zero)" % tax_text
                )
            tax = tax_text.lower()
        catalog[sku] = Product(sku, name, price, to_int(reorder_text), tax)
    return catalog


# --------------------------------------------------------------------------- movements


def sorted_movements(movements):
    """Movements in the order they count: by date, file order on ties."""
    return sorted(movements, key=lambda m: m.date)


def find_negative(movements) -> Optional[Movement]:
    """The first movement (in counting order) that takes its SKU below zero, or None."""
    running = {}  # type: Dict[str, int]
    for move in sorted_movements(movements):
        total = running.get(move.sku, 0) + move.quantity
        running[move.sku] = total
        if total < 0:
            return move
    return None


def parse_movements(text: str, catalog) -> List[Movement]:
    moves = []  # type: List[Movement]
    for number, line in iter_lines(text):
        parts = _SEP_RE.split(line, 3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date = parse_date(parts[0])
        if date is None:
            raise ParseError(number, "bad date %r (expected a real YYYY-MM-DD)" % parts[0])
        sku = norm_sku(parts[1])
        if sku is None or sku not in catalog:
            raise ParseError(number, "unknown SKU %r" % parts[1])
        if not _MOVE_QTY_RE.fullmatch(parts[2]):
            raise ParseError(number, "bad quantity %r (whole number, optional sign)" % parts[2])
        quantity = to_int(parts[2])
        if quantity == 0:
            raise ParseError(number, "quantity must not be zero")
        note = parts[3].strip(WS) if len(parts) == 4 else ""
        moves.append(Movement(date, sku, quantity, note, number))
    bad = find_negative(moves)
    if bad is not None:
        raise ParseError(bad.line, "stock of %s would go below zero" % bad.sku)
    return moves


# --------------------------------------------------------------------------- orders


def parse_orders(text: str, catalog) -> List[Order]:
    orders = []  # type: List[Order]
    seen = set()
    for number, line in iter_lines(text):
        parts = _SEP_RE.split(line)
        if len(parts) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id = norm_order_id(parts[0])
        if order_id is None:
            raise ParseError(number, "bad order number %r (expected like SO-1001)" % parts[0])
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        date = parse_date(parts[1])
        if date is None:
            raise ParseError(number, "bad date %r (expected a real YYYY-MM-DD)" % parts[1])
        lines = []  # type: List[Tuple[str, int]]
        used = set()
        for token in parts[3].split(","):
            pair = token.split("*")
            if len(pair) != 2:
                raise ParseError(number, "bad order line %r (expected SKU*QUANTITY)" % token)
            sku = norm_sku(pair[0])
            if sku is None or sku not in catalog:
                raise ParseError(number, "unknown SKU %r" % pair[0])
            if sku in used:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            if not is_positive_whole(pair[1]):
                raise ParseError(
                    number, "bad quantity %r (whole number of one or more)" % pair[1]
                )
            used.add(sku)
            lines.append((sku, to_int(pair[1])))
        seen.add(order_id)
        orders.append(Order(order_id, date, parts[2], lines, number))
    return orders
"""Stock levels, status, history and movement appending."""

