    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)

# command -> (flag options, valued options, min positionals, max positionals, files needed)
_SHELVES = ("catalog.txt", "movements.txt")
_COMMANDS = {
    "stock": (("--json",), (), 0, 0, _SHELVES),
    "low": (("--json",), (), 0, 0, _SHELVES),
    "history": (("--json",), (), 1, 1, _SHELVES),
    "receive": ((), (), 3, 4, _SHELVES),
    "ship": ((), (), 3, 4, _SHELVES),
