    "report": ((), ("--format",), 0, 0, ("catalog.txt", "movements.txt", "orders.txt")),
}
_FREE_ARGS = ("receive", "ship", "fulfil")


class CliError(Exception):
    def __init__(self, code, message, usage=False):
        super().__init__(message)
        self.code = code
        self.message = message
        self.usage = usage


def _usage_error(message):
    return CliError(2, message, usage=True)


# --------------------------------------------------------------------------- command line


def _extract_dir(argv):
    """Pull ``--dir DIR`` / ``--dir=DIR`` out of the arguments wherever it appears."""
    directory = None
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise _usage_error("option --dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    return directory, rest


def _parse_command_line(argv):
    directory, rest = _extract_dir(argv)
    if not rest:
        raise _usage_error("no command given")
    command = rest[0]
    if command not in _COMMANDS:
        raise _usage_error("unknown command %r" % command)
    flags, valued, low, high, _files = _COMMANDS[command]
    args = rest[1:]
    positional = []
    options = {}
    if command in _FREE_ARGS:
        positional = args
    else:
        i = 0
        terminated = False
        while i < len(args):
            arg = args[i]
            if terminated or arg == "-" or not arg.startswith("-"):
                positional.append(arg)
            elif arg == "--":
                terminated = True
            elif arg in flags:
                options[arg] = True
            elif arg in valued:
                if i + 1 >= len(args):
                    raise _usage_error("option %s needs a value" % arg)
                options[arg] = args[i + 1]
                i += 1
            elif arg.split("=", 1)[0] in valued and "=" in arg:
                name, value = arg.split("=", 1)
                options[name] = value
            else:
                raise _usage_error("unknown option %r" % arg)
            i += 1
    if not low <= len(positional) <= high:
        raise _usage_error("wrong number of arguments for %s" % command)
    if options.get("--format", "text") not in ("text", "csv", "json"):
        raise _usage_error("bad value for --format: %r (text, csv or json)" % options["--format"])
    if command in ("receive", "ship") and parse_date(positional[0]) is None:
        raise _usage_error("bad date %r (expected a real YYYY-MM-DD)" % positional[0])
    if command == "fulfil" and parse_date(positional[1]) is None:
        raise _usage_error("bad date %r (expected a real YYYY-MM-DD)" % positional[1])
    return command, positional, options, directory if directory is not None else "."


# --------------------------------------------------------------------------- files


def _load(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        if required:
            raise CliError(2, "%s: file not found" % path)
        return path, b"", ""
    except OSError as exc:
        raise CliError(2, "%s: cannot read: %s" % (path, exc.strerror or exc))
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError(2, "%s: not valid UTF-8" % path)
    return path, raw, text


def _parsed(path, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise CliError(1, "%s: %s" % (path, exc))


class _Data(object):
    """The files one command needs, read first and parsed after."""

    def __init__(self, directory, files):
        if not os.path.isdir(directory):
            raise CliError(2, "%s: not a directory" % directory)
        loaded = {
            name: _load(directory, name, required=(name == "catalog.txt")) for name in files
        }
        self.paths = {name: loaded[name][0] for name in files}
        self.raw = {name: loaded[name][1] for name in files}
        self.catalog = _parsed(self.paths["catalog.txt"], parse_catalog, loaded["catalog.txt"][2])
        self.movements = []
        self.orders = []
        if "movements.txt" in loaded:
            self.movements = _parsed(
                self.paths["movements.txt"], parse_movements, loaded["movements.txt"][2], self.catalog
            )
        if "orders.txt" in loaded:
            self.orders = _parsed(
                self.paths["orders.txt"], parse_orders, loaded["orders.txt"][2], self.catalog
            )

    def order(self, text):
        order_id = norm_order_id(text)
        for order in self.orders:
            if order.id == order_id:
                return order
        raise CliError(1, "unknown order %s" % text)

    def sku(self, text):
        sku = norm_sku(text)
        if sku is None or sku not in self.catalog:
            raise CliError(1, "unknown SKU %s" % text)
        return sku

    def append(self, moves):
        """Append movements to movements.txt after checking the whole list still holds."""
        bad = find_negative(self.movements + moves)
        if bad is not None:
            where = "movements.txt line %d" % bad.line if bad.line else "the new movement"
            raise CliError(
                1,
                "refused: stock of %s would go below zero (%s, %s)"
                % (bad.sku, bad.date.isoformat(), where),
            )
        data = "".join(format_movement(m) + "\n" for m in moves).encode("utf-8")
        raw = self.raw["movements.txt"]
        if raw and not raw.endswith(b"\n"):
            data = b"\n" + data
        path = self.paths["movements.txt"]
        try:
            with open(path, "ab") as handle:
                handle.write(data)
        except OSError as exc:
            raise CliError(2, "%s: cannot write: %s" % (path, exc.strerror or exc))


# --------------------------------------------------------------------------- output


def _json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def _amount(value):
    return format(value, "f")


def _lines(rows):
    return "".join(row + "\n" for row in rows)


def _quote_object(order, quote):
    return {
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {
                "sku": line.sku,
                "quantity": line.quantity,
                "unit": _amount(line.unit),
                "gross": _amount(line.gross),
                "discount": _amount(line.discount),
                "net": _amount(line.net),
            }
            for line in quote.lines
        ],
        "subtotal": _amount(quote.subtotal),
        "order_discount": _amount(quote.order_discount),
        "tax": _amount(quote.tax),
        "total": _amount(quote.total),
    }


def _quote_text(header, quote):
    rows = [header]
    for line in quote.lines:
        rows.append(
            "%s %d %s %s %s %s"
            % (
                line.sku,
                line.quantity,
                _amount(line.unit),
                _amount(line.gross),
                _amount(line.discount),
                _amount(line.net),
            )
        )
    rows.append("subtotal " + _amount(quote.subtotal))
    rows.append("order discount " + _amount(quote.order_discount))
    rows.append("tax " + _amount(quote.tax))
    rows.append("total " + _amount(quote.total))
    return _lines(rows)


# --------------------------------------------------------------------------- commands


def _cmd_stock(data, _pos, opts):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        rows.append((sku, product.name, levels[sku], stock_status(levels[sku], product.reorder)))
    if "--json" in opts:
        return _json(
            [{"sku": s, "name": n, "onhand": q, "status": st} for s, n, q, st in rows]
        )
    return _lines("%s %d %s %s" % (s, q, st, n) for s, n, q, st in rows)


def _cmd_low(data, _pos, opts):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        if stock_status(levels[sku], product.reorder) != "ok":
            rows.append(
                (sku, levels[sku], product.reorder, buy_quantity(levels[sku], product.reorder))
            )
    if "--json" in opts:
        return _json(
            [{"sku": s, "onhand": q, "reorder": r, "buy": b} for s, q, r, b in rows]
        )
    return _lines("%s %d %d %d" % row for row in rows)


def _cmd_history(data, pos, opts):
    rows = history(data.sku(pos[0]), data.movements)
    if "--json" in opts:
        return _json(
            [
                {
                    "date": m.date.isoformat(),
                    "delta": "%+d" % m.quantity,
                    "balance": balance,
                    "note": m.note,
                }
                for m, balance in rows
            ]
        )
    out = []
    for m, balance in rows:
        line = "%s %+d %d" % (m.date.isoformat(), m.quantity, balance)
        out.append(line + " " + m.note if m.note else line)
    return _lines(out)


def _cmd_move(sign):
    def run(data, pos, _opts):
        date = parse_date(pos[0])
        sku = data.sku(pos[1])
        if not is_positive_whole(pos[2]):
            raise CliError(1, "bad quantity %r (a whole number of one or more)" % pos[2])
        note = pos[3].strip(WS) if len(pos) == 4 else ""
        if "\n" in note or "\r" in note:
            raise CliError(1, "a note may not contain a line break")
        try:
            note.encode("utf-8")
        except UnicodeEncodeError:
            raise CliError(2, "the note is not valid UTF-8 text")
        move = Movement(date, sku, sign * to_int(pos[2]), note)
        data.append([move])
        return _lines([format_movement(move)])

    return run


def _cmd_quote(data, pos, opts):
    order = data.order(pos[0])
    quote = price_order(order, data.catalog)
    if "--json" in opts:
        return _json(_quote_object(order, quote))
    return _quote_text("%s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def _cmd_invoice(data, pos, opts):
    order = data.order(pos[0])
    shipped = shipped_order(order, shipped_quantities(order, data.movements))
    if not shipped.lines:
        raise CliError(1, "nothing shipped yet for %s" % order.id)
    quote = price_order(shipped, data.catalog)
    if "--json" in opts:
        return _json(_quote_object(order, quote))
    header = "invoice %s %s %s" % (order.id, order.date.isoformat(), order.customer)
    return _quote_text(header, quote)


def _cmd_fulfil(data, pos, _opts):
    order = data.order(pos[0])
    date = parse_date(pos[1])
    if date < order.date:
        raise CliError(1, "cannot fulfil %s on %s: before the order date" % (order.id, pos[1]))
    before = shipped_quantities(order, data.movements)
    moves = []
    rows = []
    after = {}
    for sku, qty in order.lines:
        owed = qty - before[sku]
        send = min(owed, available_on(sku, data.movements, date))
        if send > 0:
            moves.append(Movement(date, sku, -send, "order " + order.id))
        after[sku] = before[sku] + send
        rows.append("%s shipped %d backordered %d" % (sku, send, owed - send))
    if moves:
        data.append(moves)
    rows.append("status " + order_status(order, after))
    return _lines(rows)


def _cmd_report(data, _pos, opts):
    rows = report_rows(data.orders, data.catalog, data.movements)
    fmt = opts.get("--format", "text")
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    if fmt == "json":
        return _json(
            [
                {k: (_amount(r[k]) if k in ("quoted", "invoiced") else r[k]) for k in keys}
                for r in rows
            ]
        )
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(keys)
        for r in rows:
            writer.writerow(
                [_amount(r[k]) if k in ("quoted", "invoiced") else r[k] for k in keys]
            )
        return buffer.getvalue()
    return _lines(
        "%s %s %s %s %d/%d %s %s"
        % (
            r["order"],
            r["date"],
            r["customer"],
            r["status"],
            r["shipped"],
            r["ordered"],
            _amount(r["quoted"]),
            _amount(r["invoiced"]),
        )
        for r in rows
    )


_HANDLERS = {
    "stock": _cmd_stock,
    "low": _cmd_low,
    "history": _cmd_history,
    "receive": _cmd_move(1),
    "ship": _cmd_move(-1),
    "quote": _cmd_quote,
    "invoice": _cmd_invoice,
    "fulfil": _cmd_fulfil,
    "report": _cmd_report,
}


# --------------------------------------------------------------------------- entry point


def _silence_stdout():
    """After a broken pipe or a failed write, point stdout at /dev/null so exit is quiet."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
        os.close(fd)
    except (OSError, ValueError, AttributeError):
        pass


def _emit(text):
    if not text:
        return 0
    try:
        out = sys.stdout
        buffer = getattr(out, "buffer", None)
        if buffer is not None:
            out.flush()
            buffer.write(text.encode("utf-8"))
            buffer.flush()
        else:
            out.write(text)
            out.flush()
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _silence_stdout()
        sys.stderr.write("stockroom: cannot write output: %s\n" % (exc.strerror or exc))
        return 2
    return 0


def main(argv=None):
    """Run the command line; returns the exit status (0, 1 or 2)."""
    if argv is None:
        argv = sys.argv[1:]
    argv = list(argv)
    limit = getattr(sys, "get_int_max_str_digits", None)
    previous = limit() if limit else None
    if previous is not None:
        sys.set_int_max_str_digits(0)
    try:
        try:
            command, positional, options, directory = _parse_command_line(argv)
            data = _Data(directory, _COMMANDS[command][4])
            text = _HANDLERS[command](data, positional, options)
        except CliError as exc:
            message = "stockroom: " + exc.message if exc.code == 2 and exc.usage else exc.message
            sys.stderr.write(message + "\n")
            if exc.usage:
                sys.stderr.write(USAGE + "\n")
            return exc.code
        return _emit(text)
    finally:
        if previous is not None:
            sys.set_int_max_str_digits(previous)


if __name__ == "__main__":
    sys.exit(main())
